(() => {
 'use strict';
 // Analytic teaching calculations. No solver runs, decks or measured data.
 const ui=window.BeamLabs.ui, chart=window.BeamLabs.graphics.chart;
 const fmt=(x,n=4)=>Number.isFinite(x)?Number(x.toPrecision(n)).toLocaleString('en-US',{maximumFractionDigits:7}):'—';
 const range=(a,b,n=241)=>Array.from({length:n},(_,i)=>a+(b-a)*i/(n-1));
 const out=(e,v)=>Object.entries(v).forEach(([k,x])=>{if(e.out[k])e.out[k].textContent=fmt(+x);});
 const table=(h,r)=>window.LessonArticle.table(h,r,{narrow:true});
 const frame=(c,caption)=>ui.box('',c,caption);
 const k=100,m=.01,wn=100,fn=wn/(2*Math.PI);
 const core={
  k,m,wn,fn,
  free:(z,t)=>{if(z<1){const d=wn*Math.sqrt(1-z*z);return Math.exp(-z*wn*t)*(Math.cos(d*t)+z*wn/d*Math.sin(d*t));}if(z===1)return (1+wn*t)*Math.exp(-wn*t);const a=-wn*(z-Math.sqrt(z*z-1)),b=-wn*(z+Math.sqrt(z*z-1));return (-b*Math.exp(a*t)+a*Math.exp(b*t))/(a-b);},
  amp:(r,z)=>1/Math.hypot(1-r*r,2*z*r),
  loss:(c,w,U)=>Math.PI*c*w*U*U,
  identify:(z,n,half=false)=>{const td=2*Math.PI/(wn*Math.sqrt(1-z*z)),t=n*td*(half?.5:1),a=Math.exp(-z*wn*t),delta=Math.log(1/a)/n;return {td,t,a,delta,estimate:delta/Math.sqrt(4*Math.PI**2+delta**2)};},
  lookup:(f,descending=false)=>.02+(f-10)*(descending?-.01:.02)/30,
  fit:(f1,f2,z1,z2)=>{const w1=2*Math.PI*f1,w2=2*Math.PI*f2,b=2*(z2*w2-z1*w1)/(w2*w2-w1*w1),a=2*z1*w1-b*w1*w1;return {a,b};},
  ray:(a,b,f)=>a/(4*Math.PI*f)+b*Math.PI*f,
  local:(c,between=true)=>{const C=between?[[c,-c],[-c,c]]:[[c,0],[0,0]],p=[[1,1],[1,-1]],B=p.map(v=>p.map(w=>v.reduce((s,x,i)=>s+x*C[i].reduce((t,y,j)=>t+y*w[j],0),0)));return {C,B,z:[B[0][0]/4,B[1][1]/8]};},
  equivalent:(g,W,f)=>W===0?0:g*2*Math.PI*f/(2*W),
  sample:(z,step,half)=>{const offset=half?step/2:0,pts=[];for(let i=-50;i<=50;i++){const r=1+i*step+offset;if(r>=.85&&r<=1.15)pts.push([r,core.amp(r,z)]);}const peak=1/(2*z*Math.sqrt(1-z*z)),best=Math.max(...pts.map(p=>p[1]));return {pts,peak,best,rpeak:Math.sqrt(1-2*z*z)};}
 };
 const plot=(id,label,x,y,series,extra={})=>chart({id:'damp-'+id,label,x,y,xt:range(...x,5),yt:range(...y,5),xf:v=>fmt(v,3),yf:v=>fmt(v,3),xl:'f (Hz)',yl:'ζ',legend:true,series,...extra}).replace(/(<text x="348"[^>]*text-anchor=)"middle"/g,'$1"end"');
 const svg=(b,label,h=210)=>`<svg class="theory-lab-svg" viewBox="0 0 360 ${h}" role="img" aria-label="${label}">${b}</svg>`;
 const line=(x1,y1,x2,y2,c='el-edge')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="${c}"/>`;
 const txt=(x,y,s)=>`<text x="${x}" y="${y}" text-anchor="middle">${s}</text>`;
 const labs={
  conversion:{html:()=>frame(ui.slider('z','減衰比 ζ（%）',.5,10,.5,2)+ui.select('mass','質量 m（t）',[[.01,'0.01 t = 10 kg'],[.04,'0.04 t = 40 kg']],.01),'k = 100 N/mmの1自由度。ζを一定にしても、質量が変われば臨界減衰係数と必要なcが変わります。表のGとQはTABDMP1での値です。'),draw(e,v){out(e,v);const z=+v.z/100,mass=+v.mass,cr=2*Math.sqrt(k*mass),f=Math.sqrt(k/mass)/(2*Math.PI);e.plot.innerHTML=table(['量','値','単位'],[['fₙ',fmt(f),'Hz'],['c_crit',fmt(cr),'N·s/mm'],['c = ζ c_crit',fmt(z*cr),'N·s/mm'],['TABDMP1: CRIT',fmt(z),'無次元'],['TABDMP1: G',fmt(2*z),'無次元'],['TABDMP1: Q',fmt(1/(2*z)),'無次元']]);e.readout.innerHTML=`<strong>${v.z}% = ${fmt(z)}</strong>。${v.z}をそのままCRITへ入れると100倍です。TYPE空欄はGなので、数値${fmt(z)}を入れた場合の減衰比は${fmt(z*50)}%になります。`; }},
  energy:{html:()=>frame(ui.slider('f','振動数 f（Hz）',5,40,1,16)+ui.slider('U','変位振幅 U（mm）',.25,2,.25,1),'1自由度を外から一定振幅で動かす比較です。c = 0.04 N·s/mm、k = 100 N/mm。実線はばね＋粘性抵抗に必要な外力、破線はばね力だけ。囲まれた面積が1周期の損失です。下図はばね力を差し引いたF−ku=cvだけを別の縦軸で表示し、細いループを読みやすくしています。弾性の仕事は1周期で0なので面積は同じです。'),draw(e,v){out(e,v);const f=+v.f,U=+v.U,w=2*Math.PI*f,c=.04,pts=range(0,2*Math.PI).map(t=>[U*Math.cos(t),k*U*Math.cos(t)-c*w*U*Math.sin(t)]),y=1.2*U*Math.hypot(k,c*w);e.plot.innerHTML=plot('energy','力と変位の履歴ループ',[-U*1.2,U*1.2],[-y,y],[{pts,name:'ku + cv',strong:true},{pts:[[-U,-k*U],[U,k*U]],name:'ku',dash:'7 4'}],{xl:'u (mm)',yl:'F (N)'})+plot('loss-only','ばね力を差し引いて損失の面積を見る',[-U*1.2,U*1.2],[-1.2*c*w*U,1.2*c*w*U],[{pts:range(0,2*Math.PI).map(t=>[U*Math.cos(t),-c*w*U*Math.sin(t)]),name:'F − ku = cv',strong:true}],{xl:'u (mm)',yl:'F − ku (N)'});e.readout.innerHTML=`速度振幅 ωU = ${fmt(w*U)} mm/s、抵抗力振幅 cωU = ${fmt(c*w*U)} N。<strong>ΔE = ${fmt(core.loss(c,w,U))} N·mm/周期</strong>。Uを2倍にすると損失は4倍。fを2倍にすると、同じUで損失は2倍です。`; }},
  identify:{html:()=>frame(ui.slider('z','真の減衰比 ζ（%）',1,10,1,2)+ui.slider('n','数える周期数 n',1,8,1,3)+ui.select('peaks','ピークの選び方',[['positive','同じ符号のピーク同士'],['half','誤り：正負の絶対値を1周期と数える']],'positive'),'初期変位1 mm、初速度0の理論解。点は最初と比較対象のピークの絶対値を示します。実測データではノイズ、多数のモード、時間窓の影響を別に確認します。'),draw(e,v){out(e,v);const z=+v.z/100,n=+v.n,r=core.identify(z,n,v.peaks==='half'),tmax=8.2*r.td; e.plot.innerHTML=plot('identify','自由減衰のピークから減衰比を求める',[0,tmax],[-1,1],[{pts:range(0,tmax,650).map(t=>[t,core.free(z,t)]),name:'u',strong:true},{pts:range(0,tmax).map(t=>[t,Math.exp(-z*wn*t)]),name:'exp(−ζωₙt)',dash:'7 4'}],{xl:'t (s)',yl:'u (mm)',marks:[[0,1],[r.t,r.a]]});e.readout.innerHTML=`A0 = 1、An = ${fmt(r.a)} mm。δ = ln(A0/An)/n = ${fmt(r.delta)}。<strong>推定ζ = ${fmt(100*r.estimate)}%</strong>。${v.peaks==='half'?'正負のピークは半周期間隔です。1周期と数えたため、約半分に誤推定しています。':'既知の減衰比と一致します。複数周期で求めると、ピーク読取り誤差の影響を抑えやすくなります。'}`; }},
  modalTable:{html:()=>frame(ui.select('shape','表の形',[['up','10 Hz: 0.02 → 40 Hz: 0.04'],['down','10 Hz: 0.02 → 40 Hz: 0.01']],'up')+ui.select('type','同じ表の数字を解釈するTYPE',[['CRIT','CRIT'],['G','G（空欄の既定）']],'CRIT')+ui.slider('fi','モードの固有振動数 fi（Hz）',5,100,1,25)+ui.slider('f','加振周波数 f（Hz）',5,100,1,60),'線は表の補間・外挿、丸は固有振動数fiで読む減衰比、破線の縦線は加振周波数fです。表の外を読んだ値は、そのまま妥当とは判断しません。'),draw(e,v){out(e,v);const fi=+v.fi,f=+v.f,scale=v.type==='G'?.5:1,z=x=>core.lookup(x,v.shape==='down')*scale,value=z(fi);e.plot.innerHTML=plot('modal','モードの周波数と加振周波数を区別する',[0,105],[-.02,.09],[{pts:range(5,100).map(x=>[x,z(x)]),name:v.type,strong:true},{pts:[[f,-.02],[f,.09]],name:'f',dash:'7 4'}],{xl:'fᵢ (Hz)',marks:[[fi,value]],dots:[[10,z(10)],[40,z(40)]]});e.readout.innerHTML=`<strong>このモードのζ = ${fmt(value*100)}%</strong>（fi = ${fi} Hzで評価）。加振周波数を${f} Hzへ動かしても、モードに割り当てた値は変わりません。${fi<10||fi>40?'表の範囲外なので外挿です。':''}${value<0?'負の減衰です。通常の散逸を表す設定として採用せず、表の範囲と値を修正します。':''}`; }},
  rayleigh:{html:()=>frame(ui.slider('f2','高い側の合わせ込み f2（Hz）',20,80,5,40)+ui.select('target','2点の目標ζ',[['equal','f1=10 Hzで2%、f2でも2%'],['fall','f1=10 Hzで2%、f2で0.1%']],'equal'),'丸の2点で減衰比を合わせます。実線が合計、破線が質量比例項、点線が剛性比例項です。目標が両立しない場合も値を隠さず、負の係数と帯域外の影響を確認します。'),draw(e,v){out(e,v);const f2=+v.f2,z2=v.target==='fall'?.001:.02,r=core.fit(10,f2,.02,z2),z=f=>core.ray(r.a,r.b,f),xs=range(5,100),ymin=Math.min(0,...xs.map(z)),ymax=Math.max(.025,...xs.map(z));e.plot.innerHTML=plot('ray','二点合わせ込みと帯域外のRayleigh減衰',[5,100],[ymin*1.2,ymax*1.1],[{pts:xs.map(f=>[f,z(f)]),name:'ζ',strong:true},{pts:xs.map(f=>[f,r.a/(4*Math.PI*f)]),name:'α/(2ω)',dash:'7 4'},{pts:xs.map(f=>[f,r.b*Math.PI*f]),name:'βω/2',dash:'2 4'}],{marks:[[10,.02],[f2,z2]]});e.readout.innerHTML=`<strong>α = ${fmt(r.a)} s⁻¹、β = ${fmt(r.b)} s</strong>。5 Hzで${fmt(z(5)*100)}%、100 Hzで${fmt(z(100)*100)}%。${r.a<0||r.b<0?'負の係数が必要な目標です。帯域外でエネルギーを与える設定になるおそれがあり、この2係数近似の採用を見直します。':'2点の間も外も、目標と同じ一定値にはなりません。'}`; }},
  local:{html:()=>frame(ui.select('site','同じダンパーcの配置',[['between','2つの質量の間'],['ground','質量1と地面の間']],'between')+ui.select('mode','見るモード',[['0','1次：2点が同じ向き'],['1','2次：2点が逆向き']],'0')+ui.slider('c','粘性係数 c（N·s/mm）',.01,.08,.01,.04),'同じ質量m=0.01 tを2個、各点と地面のばねk=100 N/mm、点間ばねkc=150 N/mm。固有角振動数は100・200 rad/s、モード形は(1,1)と(1,−1)。緑の矢印はモードの動く向きです。'),draw(e,v){out(e,v);const i=+v.mode,c=+v.c,r=core.local(c,v.site==='between'),sign=i? -1:1;const damper=(x1,x2,y)=>line(x1,y,x1+12,y)+`<path d="M${x1+12} ${y-9}H${x2-12}V${y+9}H${x1+12} M${x1+22} ${y-6}V${y+6} M${x1+22} ${y}H${x2}" class="el-edge"/>`; const spring=(a,b,y)=>{const pts=[[a,y],[a+6,y]];for(let j=1;j<9;j++)pts.push([a+6+(b-a-12)*j/9,y+(j%2?5:-5)]);pts.push([b-6,y],[b,y]);return `<polyline points="${pts.map(p=>p.join(',')).join(' ')}" class="el-edge"/>`;};
    const wall=x=>line(x,68,x,151)+[0,1,2,3,4,5].map(j=>line(x,72+j*14,x+(x<180?-8:8),80+j*14)).join('');
    e.plot.innerHTML=svg(`${wall(20)}${wall(340)}<rect x="85" y="75" width="48" height="45" class="el-fill"/><rect x="235" y="75" width="48" height="45" class="el-fill"/>${txt(109,102,'m1')}${txt(259,102,'m2')}${spring(20,85,96)}${spring(283,340,96)}${spring(133,235,80)}${txt(52,78,'k')}${txt(312,78,'k')}${txt(184,59,'kc')}${line(109,35,140,35,'el-motion')}<polygon points="140,35 132,31 132,39" class="el-motion-head"/>${line(259,35,259+31*sign,35,'el-motion')}<polygon points="${259+31*sign},35 ${259+23*sign},31 ${259+23*sign},39" class="el-motion-head"/>${v.site==='between'?line(133,97,133,136)+line(235,97,235,136)+damper(133,235,136):line(85,97,85,136)+damper(20,85,136)}${txt(v.site==='between'?184:53,160,'c')}${txt(180,197,i?'φ2 = (1, −1)':'φ1 = (1, 1)')}`,'ダンパー両端の相対運動',220)+table(['Cmodal (N·s/mm)','φ1','φ2'],r.B.map((row,j)=>['φ'+(j+1),...row.map(x=>fmt(x))]));e.readout.innerHTML=`選んだモードの対角項から換算すると<strong>ζ${i+1} = ${fmt(r.z[i]*100)}%</strong>。${v.site==='between'?(i?'逆向きの相対運動が大きく、減衰が効きます。':'同じ向きに同じ量だけ動くため、両端の速度差が0。cを増やしても効きません。'):'非対角項も存在します。この対角項の値だけを独立モードの減衰として置き換えると、連成を落とします。'}`; }},
  conversionW:{html:()=>frame(ui.select('W','換算に指定するW（rad/s）',[[100,'100：正しい換算周波数'],[fn,'15.9155：Hzをそのまま入力した誤り'],[0,'0：既定のまま']],100),'g=0.04の剛性比例の構造減衰を、指定Wで粘性へ換算したときの各モードの相当減衰比。丸は約7.96、15.9、31.8 Hzの3モードです。'),draw(e,v){const W=+v.W,z=f=>core.equivalent(.04,W,f);e.plot.innerHTML=plot('w','構造減衰を過渡用に換算する周波数',[0,40],[0,.35],[{pts:range(.01,40).map(f=>[f,z(f)]),name:'ζeq',strong:true},{pts:[[0,.02],[40,.02]],name:'0.02',dash:'7 4'}],{marks:[fn/2,fn,fn*2].map(f=>[f,z(f)])});e.readout.innerHTML=`基準モードfn=${fmt(fn)} Hzで<strong>ζeq = ${fmt(z(fn)*100)}%</strong>。${W===0?'このG由来の換算項は無視されます。他に指定した粘性要素やモード減衰まで消えるという意味ではありません。':W<20?'Hzの数値をrad/s欄へ入れたため、基準の減衰比が2π倍になっています。':'半分の固有振動数では1%、2倍では4%。全モードが2%になる換算ではありません。'}`; }},
  sampling:{html:()=>frame(ui.slider('z','減衰比 ζ（%）',.5,5,.5,1)+ui.select('step','計算点の間隔 Δr',[[.005,'0.005'],[.02,'0.02'],[.08,'0.08']],.02)+ui.select('offset','計算点の置き方',[['half','r=1を点の間に置く'],['on','r=1に点を置く']],'half'),'実線は力加振の1自由度の理論曲線、丸は指定した周波数点の結果です。横軸r=f/fn。線のピークを丸が捉えているか比較してください。'),draw(e,v){out(e,v);const z=+v.z/100,r=core.sample(z,+v.step,v.offset==='half');e.plot.innerHTML=plot('sampling','粗い周波数刻みによるピークの見落とし',[.85,1.15],[0,r.peak*1.1],[{pts:range(.85,1.15,601).map(x=>[x,core.amp(x,z)]),name:'U/us',strong:true}],{xl:'r = f/fₙ',yl:'U/us',dots:r.pts});e.readout.innerHTML=`真の最大倍率 ${fmt(r.peak)} に対し、計算点の最大は<strong>${fmt(r.best)}（${fmt(100*r.best/r.peak)}%）</strong>。低いピークを減衰が大きい証拠と即断せず、先に刻みを細かくします。`; }}
 };
 // Existing Claude charts are reused without modifying their geometry/style. Only
 // visible legend prose is replaced with symbols; the explanations live in captions.
 const legacyCaptions={
  'lab-convert':'初期変位1 mm、初速度0、ωn=100 rad/s。固定した4ケースの自由振動比較です。実線ζ=0.02、破線0.2、点線1、一点鎖線2。これは係数換算の操作とは独立した比較図です。',
  'lab-visc-struct':'r=1で同じ減衰になるようg=2ζにした比較。実線は粘性、破線は構造減衰です。共振以外の振動数では効き方が異なります。',
  'lab-rayleigh':'従来の計算例：ω=50・200 rad/sでζ=2%に合わせた結果。α=1.6 s⁻¹、β=0.00016 s。2点の間のω=100 rad/sでは1.6%です。'};
 function mountLegacy(fig){const name=fig.dataset.dampingLegacy,legacy=window.TheoryLabs.labs[name];ui.mount(fig,{html:()=>frame(name==='lab-visc-struct'?ui.select('z','比較する粘性のζ',[[.01,'0.01'],[.02,'0.02'],[.05,'0.05'],[.1,'0.1']],.02):'',legacyCaptions[name]),draw(e,v){legacy.draw(e,{z:.02,...v});if(name==='lab-convert'){e.plot.querySelector('table')?.remove();e.readout.textContent='ζ=1は、この初期条件では揺れずに最も速く戻る境界。ζ=2にすると、かえって尾を引きます。';}for(const t of e.plot.querySelectorAll('svg text')){t.textContent=t.textContent.replace('粘性 ','').replace('構造 ','');if(t.getAttribute('transform')?.startsWith('rotate(-90 12 ')){t.setAttribute('x','14');t.setAttribute('transform',t.getAttribute('transform').replace('rotate(-90 12 ','rotate(-90 14 '));}}}});}
 function connect(root){for(const f of root.querySelectorAll('[data-damping-lab]'))ui.mount(f,labs[f.dataset.dampingLab]);for(const f of root.querySelectorAll('[data-damping-legacy]'))mountLegacy(f);}
 window.DampingLabs={core,labs,connect};
})();
